import { lazy, Suspense } from "react";
import { BrowserRouter, Route, Routes } from "react-router-dom";
import NotFound from "./pages/NotFound";
import { OptionSwitcher, type SiteOption } from "@/components/OptionSwitcher";
import P1 from "@/sections/01-page";
const load2 = () => import("@/sections/02-page");
const P2 = lazy(load2);
const load3 = () => import("@/sections/03-page");
const P3 = lazy(load3);

// Options built for this brief (generated by the website engine: npm run site -- switcher <slug>).
const OPTIONS: SiteOption[] = [
  { path: "/", number: "01", name: "Architecture Studio", tagline: "Editorial, elegant studio page with 7 of 8 sections; closest fit for a design practice, though cooler than Form & Function's warmth and lacks a process section.", swatches: ["#ffffff","#c83c3c","#2c5f8a"] },
  { path: "/option-2", number: "02", name: "Carpenter", tagline: "Warm craft feel (88% match) suits oak, walnut and handmade details; only 3 of 8 sections, so services and projects need building.", swatches: ["#ffffff","#000000","#2a1d0d"], preload: load2 },
  { path: "/option-3", number: "03", name: "Interior Design", tagline: "Built for interior design with elegant, warm editorial styling and top quality, but covers only 3 of 8 sections.", swatches: ["#23221f","#4c4a44","#7d7a72"], preload: load3 },
];

const App = () => (
  <BrowserRouter>
    <Suspense fallback={<div style={{ minHeight: "100vh" }} />}>
      <Routes>
        <Route path="/" element={<P1 />} />
        <Route path="/option-2" element={<P2 />} />
        <Route path="/option-3" element={<P3 />} />
        <Route path="*" element={<NotFound />} />
      </Routes>
    </Suspense>
    <OptionSwitcher options={OPTIONS} brand={"Form & Function Studio"} kind="homepage" accent="#bfb0a0" />
  </BrowserRouter>
);

export default App;
